// Generated by secure-by-design v0.1.0 for DPDP §8(6) (Breach Notification).
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/breach_notifier.md
//
// Scaffold for personal-data-breach reporting. DPDP §8(6) requires the data
// fiduciary to notify the Data Protection Board and affected data principals
// in the event of a personal data breach. The exact form, timeline, and
// content will be specified by rules under the Act — this scaffold is a
// shape, not the final transport.

import { auditLog } from '../security/audit_log';

export type BreachSeverity = 'low' | 'medium' | 'high' | 'critical';

export interface BreachReport {
  detectedAt: Date;
  natureOfBreach: string;          // free text — what happened
  affectedCategories: string[];    // dataCategory names from manifest
  estimatedDataPrincipalsAffected: number;
  isOngoing: boolean;
  rootCauseInitial?: string;
  containmentActionsTaken: string[];
  severity: BreachSeverity;
  detectedBy: string;              // employee ID, system ID, external report
}

export interface BreachNotifier {
  /**
   * Send the notification to the Data Protection Board.
   * Replace with your actual transport once the form is notified by rules under the Act.
   */
  notifyBoard(report: BreachReport): Promise<{ ticketId: string }>;

  /**
   * Notify affected data principals through the appropriate channel.
   * Channel comes from manifest.breachNotification.dataSubjectNotifyChannel.
   */
  notifyDataPrincipals(report: BreachReport, principalIds: string[]): Promise<{ sent: number; failed: number }>;
}

let notifier: BreachNotifier | null = null;
export function setBreachNotifier(n: BreachNotifier): void { notifier = n; }

/**
 * Report a personal data breach. Always log first. Notification proceeds
 * asynchronously per your incident-response runbook.
 */
export async function reportBreach(report: BreachReport): Promise<{ ticketId?: string }> {
  await auditLog.event('breach.detected', {
    actor: report.detectedBy,
    severity: report.severity === 'critical' ? 'CRITICAL' : 'ERROR',
    attrs: {
      detectedAt: report.detectedAt.toISOString(),
      categories: report.affectedCategories,
      estimatedAffected: report.estimatedDataPrincipalsAffected,
      isOngoing: report.isOngoing,
      severity: report.severity,
    },
  });

  if (!notifier) {
    // Logged, but transport not configured. The on-call engineer must escalate manually.
    throw new Error(
      'secure-by-design: BreachNotifier not configured. Breach is logged but ' +
      'NOT yet reported to the Data Protection Board. Escalate immediately per runbook.',
    );
  }

  const boardResult = await notifier.notifyBoard(report);
  await auditLog.event('breach.board-notified', {
    actor: 'system:breach-notifier',
    attrs: { ticketId: boardResult.ticketId },
  });

  // Affected-principals notification is a separate async step in most products,
  // because identifying who-was-affected takes investigation. Trigger it once
  // your incident response has the affected-IDs list.
  return { ticketId: boardResult.ticketId };
}

/**
 * Phase 2: once the affected-IDs list is known, dispatch principal notifications.
 */
export async function notifyAffectedPrincipals(
  report: BreachReport,
  affectedIds: string[],
): Promise<{ sent: number; failed: number }> {
  if (!notifier) throw new Error('secure-by-design: BreachNotifier not configured.');
  const result = await notifier.notifyDataPrincipals(report, affectedIds);
  await auditLog.event('breach.principals-notified', {
    actor: 'system:breach-notifier',
    attrs: { ...result, attempted: affectedIds.length },
  });
  return result;
}
